function w({registerIndicator:M,nulls:x}){M({id:"oa-baxterking",name:"Baxter-King Band-Pass Filter (BAXTERKING)",category:"Filters",placement:"pane",inputs:[{key:"pLow",type:"number",label:"Min Period (pLow)",default:6,min:2,max:5e3,step:1,tooltip:"Shortest cycle to pass through (bars)."},{key:"pHigh",type:"number",label:"Max Period (pHigh)",default:32,min:3,max:5e3,step:1,tooltip:"Longest cycle to pass through (bars)."},{key:"k",type:"number",label:"Filter Half-Length (K)",default:12,min:1,max:100,step:1,tooltip:"Number of leads and lags. Larger is a better approximation but loses 2K bars. Baxter and King recommend 12 for quarterly data, 36 for monthly."}],plots:[{key:"cycle",type:"line",title:"BK Cycle",style:{color:"#2962ff",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#808080",dashed:!0}],calc(h,n){const m=Math.max(2,Math.floor(Number(n.pLow)||6)),N=Math.max(m+1,Math.floor(Number(n.pHigh)||32)),t=Math.max(1,Math.floor(Number(n.k)||12)),r=h.length,p=new Array(r).fill(NaN),u=2*Math.PI/N,f=2*Math.PI/m,a=new Array(t+1);a[0]=(f-u)/Math.PI;let y=0;for(let e=1;e<=t;e++)a[e]=(Math.sin(e*f)-Math.sin(e*u))/(Math.PI*e),y+=a[e];const k=(a[0]+2*y)/(2*t+1),i=new Array(t+1);for(let e=0;e<=t;e++)i[e]=a[e]-k;const l=new Array(r);for(let e=0;e<r;e++)l[e]=h[e].close;for(let e=0;e<r;e++){if(e<2*t)continue;const s=e-t,b=l[s];let c=i[0]*(Number.isFinite(b)?b:0);for(let o=1;o<=t;o++){const d=l[s+o],g=l[s-o];c+=i[o]*((Number.isFinite(d)?d:0)+(Number.isFinite(g)?g:0))}Number.isFinite(c)&&(p[e]=c)}return{cycle:x(p)}}})}export{w as default};
